//  Puzzles
#include <stdio.h>

int main(int argc, char *argv[])
{
    int n ,m ,i,j;
    scanf("%d%d\n",&n ,&m);
    int a[m];
    for (i=0;i<m;i++)
    {
        scanf("%d",&a[i]);
    }
    for (i=0;i<m;i++)
    {
        for (j=i+1;j<m;j++)
        {
            if (a[i] > a[j])
            {
                int t=a[i];
                a[i]=a[j];
                a[j]=t;
            }

        }

    }
    int y = a[n-1]-a[0];
    for(int i=0;i+n-1<m;i++)
        for(int j=i+n-1;j<m;j++)
            if(a[j]-a[i] < y)
                y=a[j]-a[i];


    printf("%d\n",y);
    return 0;
}"}
